class MainActivity : ComponentActivity() {

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)             // REQUIRED — otherwise getIntent() stays stale
        handleDeepLink(intent)
    }
}

// Log out: clear the whole task so back can't return to authenticated screens
fun logout(context: Context) {
    val intent = Intent(context, LoginActivity::class.java).apply {
        flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
    }
    context.startActivity(intent)
}

// Preferred: no permission at all
val pickMedia = registerForActivityResult(
    ActivityResultContracts.PickVisualMedia()
) { uri -> uri?.let { onImageSelected(it) } }

fun choosePhoto() = pickMedia.launch(
    PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)
)

// When you really need a runtime permission
private val requestPermission = registerForActivityResult(
    ActivityResultContracts.RequestPermission()
) { granted ->
    when {
        granted -> startRecording()
        shouldShowRequestPermissionRationale(Manifest.permission.RECORD_AUDIO) ->
            showRationale()                    // denied once — we may ask again
        else -> showSettingsPrompt()           // "don't ask again" — deep-link to Settings
    }
}

fun onRecordClicked() {
    when {
        ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) ==
            PackageManager.PERMISSION_GRANTED -> startRecording()
        shouldShowRequestPermissionRationale(Manifest.permission.RECORD_AUDIO) -> showRationale()
        else -> requestPermission.launch(Manifest.permission.RECORD_AUDIO)
    }
}

