private fun handleDeepLink(intent: Intent) {
    val uri = intent.data ?: return

    // 1. Validate the host — never trust it blindly
    if (uri.host != "example.com") return

    // 2. Validate the shape of every parameter
    val itemId = uri.lastPathSegment?.takeIf { it.matches(Regex("[a-zA-Z0-9_-]{1,32}")) } ?: return

    // 3. Re-check auth — the link may target a screen this user can't see
    if (!session.isAuthenticated) {
        navigateToLogin(pendingDestination = itemId)
        return
    }

    navigateToItem(itemId)
}

class PlayerFragment : Fragment(R.layout.player) {

    private var _binding: PlayerBinding? = null
    private val binding get() = _binding!!
    private var player: ExoPlayer? = null

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        _binding = PlayerBinding.bind(view)

        // viewLifecycleOwner — NOT `this`
        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.state.collect { render(it) }
            }
        }
    }

    override fun onStart() { super.onStart(); player = buildPlayer() }   // visible
    override fun onResume() { super.onResume(); player?.play() }          // interactive
    override fun onPause() { player?.pause(); super.onPause() }           // keep this fast
    override fun onStop() { player?.release(); player = null; super.onStop() }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null            // required — the fragment outlives this view
    }
}
